const cfg = readConfig();
const r1 = await probe('request');
const r2 = await probe('health');
const r3 = await probe('metadata');
const result = {
  config: cfg,
  request: r1,
  health: r2,
  metadata: r3,
  finding: r1.status === 500 ? 'Service request endpoint returns 500 error matching hypothesis.' : 'Service request endpoint did not return 500.'
};
console.log(JSON.stringify(result));
